@if (friendNote(); as note) {
  <div class="friend">
    <span class="friend-note" role="status">{{ note | t }}</span>
  </div>
} @else if (newFriend(); as opponent) {
  <div class="friend">
    <button mat-stroked-button type="button" (click)="addFriend(opponent.uid)">
      <mat-icon>person_add</mat-icon>
      {{ "match.friend.add" | t: { name: opponent.card.name } }}
    </button>
  </div>
}

@if (offersSignIn()) {
  <feat-lazy-bac-game-guest-sign-in
    class="sign-in"
    [note]="'profile.guest.success'"
  />
}

<feat-lazy-bac-game-replay-note (watch)="action.emit('watch')" />

<div class="actions">
  <button mat-button type="button" (click)="action.emit('menu')">
    <mat-icon>home</mat-icon>
    {{ "match.actions.menu" | t }}
  </button>
  @if (onlineGuest()) {
    <p class="online-wait">{{ "match.actions.guestWaits" | t }}</p>
  } @else if (online() && !connected()) {
    <p class="online-wait">{{ "match.actions.connectionGone" | t }}</p>
  } @else if (endlessAction(); as label) {
    <button mat-flat-button type="button" (click)="action.emit('endless')">
      <mat-icon>all_inclusive</mat-icon>
      {{ label | t }}
    </button>
  } @else if (mission(); as mission) {
    @if (canChooseLevel()) {
      <button mat-stroked-button type="button" (click)="action.emit('levels')">
        <mat-icon>school</mat-icon>
        {{ "training.actions.all" | t }}
      </button>
    }
    <button mat-stroked-button type="button" (click)="action.emit('again')">
      <mat-icon>replay</mat-icon>
      {{
        (mission.done ? "match.actions.playAgain" : "match.actions.tryAgain")
          | t
      }}
    </button>
    @if (mission.next) {
      <button mat-flat-button type="button" (click)="action.emit('mission')">
        <mat-icon>skip_next</mat-icon>
        {{ "training.actions.next" | t }}
      </button>
    } @else if (mission.allDone) {
      <button mat-flat-button type="button" (click)="action.emit('campaign')">
        <mat-icon>flag</mat-icon>
        {{ "training.actions.campaign" | t }}
      </button>
    }
  } @else {
    @if (canChooseLevel() && !online()) {
      <button mat-stroked-button type="button" (click)="action.emit('levels')">
        <mat-icon>grid_view</mat-icon>
        {{ "match.actions.chooseLevel" | t }}
      </button>
    }
    <button mat-stroked-button type="button" (click)="action.emit('again')">
      <mat-icon>replay</mat-icon>
      {{
        (againstGhost()
          ? "match.actions.fightAgain"
          : "match.actions.playAgain"
        ) | t
      }}
    </button>
    @if (canFightGhost()) {
      <button mat-stroked-button type="button" (click)="action.emit('ghost')">
        <mat-icon>blur_on</mat-icon>
        {{ "match.actions.fightGhost" | t }}
      </button>
      <button
        mat-button
        type="button"
        class="share"
        [disabled]="shareLink() === null"
        (click)="shareRun()"
      >
        <mat-icon>share</mat-icon>
        {{ "match.share.button" | t }}
      </button>
    }
    @if (upcoming(); as next) {
      <button
        mat-flat-button
        type="button"
        [disabled]="upcomingLock() !== null"
        (click)="action.emit('next')"
      >
        <mat-icon>{{
          upcomingLock() === null ? "skip_next" : "lock"
        }}</mat-icon>
        {{
          "match.actions.next" | t: { level: (levelNameText(next) | gameText) }
        }}
      </button>
    }
  }
</div>
@if (shareNote(); as note) {
  <p class="share-note" role="status">{{ note | t }}</p>
}
<!-- Only with a Next button for the reason to explain. -->
@if (!online() && upcomingLockText(); as lock) {
  <p class="lock-reason">{{ lock | gameText }}</p>
}
