@use 'screen';

:host {
  display: block;
}

.room {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.label {
  font-size: 0.8rem;
  color: var(--bw-muted);
}

// The two players face to face, the tally between them.
.players {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 0.5rem;
}

.player {
  @include screen.panel;

  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.3rem;
  min-width: 0;
  padding: 0.75rem 0.5rem;
  border-color: color-mix(in srgb, var(--seat-color) 45%, transparent);
  background: linear-gradient(
    180deg,
    color-mix(in srgb, var(--seat-color) 22%, transparent),
    var(--bw-surface) 75%
  );

  &.you {
    border-width: 2px;
  }

  &.won {
    border-color: var(--bw-gold);
    box-shadow: 0 0 1.25rem color-mix(in srgb, var(--bw-gold) 35%, transparent);
  }
}

.no-avatar {
  display: grid;
  place-items: center;
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--seat-color);
  color: var(--bw-ground);
}

.name {
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-weight: 700;
  color: var(--bw-text);
}

.tag {
  display: inline-flex;
  align-items: center;
  gap: 0.2rem;
  font-size: 0.75rem;
  color: var(--bw-muted);

  mat-icon {
    width: 1rem;
    height: 1rem;
    font-size: 1rem;
  }
}

.won-tag {
  color: var(--bw-gold);
}

.tally {
  @include screen.figure;

  margin: 0;
  font-size: 2rem;
  font-weight: 800;
  color: var(--bw-text);

  .colon {
    margin: 0 0.2rem;
    color: var(--bw-faint);
  }
}

.next {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

// The next match's level, flashing up whenever it changes.
.next-level {
  @include screen.panel;

  position: relative;
  display: grid;
  grid-template-columns: auto 1fr;
  align-items: center;
  gap: 0.25rem 0.75rem;
  padding: 0.75rem 1rem;
  overflow: hidden;
  background: linear-gradient(
    160deg,
    rgb(var(--card-floor, 18 24 33) / 95%),
    var(--bw-surface) 70%
  );
  border: 2px solid var(--bw-player);
  animation: picked 0.6s ease-out;
}

.next-preview {
  grid-row: span 2;
  width: 5.5rem;
}

.next-badge {
  @include screen.figure;

  color: var(--bw-player);
  font-weight: 800;
}

.next-title {
  font-family: var(--bw-display);
  font-size: 1.15rem;
  font-weight: 800;
  color: var(--bw-text);
}

// The host's levels, a strip to scroll through.
.picker {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: 9.5rem;
  gap: 0.5rem;
  overflow-x: auto;
  padding-bottom: 0.25rem;
  scroll-snap-type: x proximity;

  .pick {
    scroll-snap-align: start;
  }
}

.choosing {
  margin: 0;
  color: var(--bw-soft);
  animation: waiting 1.6s ease-in-out infinite alternate;
}

@keyframes picked {
  from {
    transform: scale(0.96);
    box-shadow: 0 0 0 0.4rem color-mix(in srgb, var(--bw-gold) 60%, transparent);
  }

  to {
    transform: none;
    box-shadow: none;
  }
}

@keyframes waiting {
  from {
    opacity: 0.6;
  }

  to {
    opacity: 1;
  }
}

@media (prefers-reduced-motion: reduce) {
  .next-level,
  .choosing {
    animation: none;
  }
}
EOF
