  /** Picks a training mission and goes on to its start. */
  protected pickMission(id: MissionId): void {
    this.busy.run(() => {
      this.missionChange.emit(id);
      this.step.set('start');
    });
  }

  /**
   * Picks a level and goes on to the start - for an online match being
   * created, it opens the match on that level too.
   */
  protected pickLevel(id: string): void {
    this.busy.run(() => {
      this.levelChange.emit(id);
      this.openCreatedMatch();
      this.step.set('start');
    });
  }

  /**
   * Opens the online match being created, on the level chosen - only from
   * a lobby still idle, where online play is available.
   */
  private openCreatedMatch(): void {
    if (
      this.creating() &&
      this.onlineAvailable() &&
      this.online().phase === 'idle'
    ) {
      this.hostOnline.emit();
    }
    this.creating.set(false);
  }

  /** The lobby's Open button: first the level of the match to open. */
  protected createOnline(): void {
    this.creating.set(true);
    this.step.set('level');
  }

  protected goTo(index: number): void {
    const step = this.steps()[index] ?? 'mode';
    if (step === 'start') {
      // On from the level of a match being created opens it on that level.
      this.openCreatedMatch();
    } else if (step !== 'level') {
      this.creating.set(false);
    }
    this.step.set(step);
  }

  protected next(): void {
    this.busy.run(() =>
      this.goTo(Math.min(this.index() + 1, this.steps().length - 1))
    );
  }

  protected goBack(): void {
    if (this.creating() && this.step() === 'level') {
      // Back from the level of a match to open is back to the lobby.
      this.creating.set(false);
      this.step.set('start');
    } else if (this.index() === 0) {
      this.back.emit();
    } else {
      this.goTo(this.index() - 1);
    }
  }

  protected startGame(): void {
