import { english, GameText } from '../../i18n/game-text';
import { clock, TICKS_PER_SEC } from '../simulation/fixed-tick';
import { Player } from './player.model';

export type WinRule =
  | { kind: 'annihilation' }
  | { kind: 'timed'; limitSec: number }
  | { kind: 'survive'; limitSec: number }
  | { kind: 'hold'; holdSec: number }
  | { kind: 'harvest'; pellets: number };

export type EndReason =
  | 'annihilation'
  | 'time'
  | 'hold'
  | 'survive'
  | 'harvest'
  /** Online: the other device left or lost the connection. */
  | 'forfeit'
  /** Online: the two devices came to different matches. */
  | 'desync';

export interface MatchOutcome {
  winner: Player | null;
  reason: EndReason;
}

export const ANNIHILATION: WinRule = { kind: 'annihilation' };

export const BOSS_SEAT = 1;

